/** Events */
export const events = {
	avatarReady: makeEvent<AvatarReady>("avatar-ready"),
	menuCommand: makeEvent<MenuCommand>("menu-command"),
	mergeResolved: makeEvent<MergeResolved>("merge-resolved"),
	operationChanged: makeEvent<OperationChanged>("operation-changed"),
	repoChanged: makeEvent<RepoChanged>("repo-changed"),
};

/* Types */
export type Algorithm = "histogram" | "myers";

/**  specta follows serde, so a DTO without `camelCase` reads `undefined` in the UI. */
export type AppInfo = {
	version: string,
	logPath: string,
	debugBuild: boolean,
};

export type Author = {
	name: string,
	email: string,
};

/**  Mirrors `app_state::AppEvent::AvatarReady`: one row can redraw without a refetch. */
export type AvatarReady = {
	email: string,
};

export type AvatarRow = {
	email: string,
	initials: string,
	color: string,
	/**  A `data:` URL, so the webview needs no access to the cache directory. */
	image: string | null,
};

export type BlameLine = {
	line: number,
	text: string,
	oid: string,
	summary: string,
	author: string,
	email: string,
	timestamp: number,
};

export type Branch = {
	name: string,
	fullName: string,
	kind: BranchKind,
	oid: string,
	isHead: boolean,
	/**  Short name of the tracking branch, e.g. `origin/main`. */
	upstream: string | null,
	ahead: number,
	behind: number,
};

export type BranchKind = "local" | "remote";

/**  Git records nothing about `--no-verify`, so Cogit keeps its own note per clone. */
export type Bypass = {
	oid: string,
	summary: string,
	at: number,
};

export type ChangeKind = "head" | "index" | "refs" | "workingTree" | "stash" | "config" | "hooks";

export type CheckoutTarget = { kind: "branch"; name: string } | { kind: "commit"; oid: string };

export type CommitDetails = {
	oid: string,
	parents: string[],
	summary: string,
	body: string,
	author: Signature,
	committer: Signature,
};

export type CommitQuery = {
	author?: string | null,
	message?: string | null,
	oidPrefix?: string | null,
	since?: number | null,
	until?: number | null,
	path?: string | null,
	/**
	 *  Revisions the References panel has ticked. `None` is every ref; `Some([])` is
	 *  nothing, which is the honest answer when the user unticks the last box.
	 */
	visibleRefs?: string[] | null,
};

export type CommitRequest = {
	message: string,
	amend: boolean,
	noVerify: boolean,
	/**  Empty means everything staged; a list narrows the commit to those paths (T6.8). */
	only?: string[],
};

export type CommitRow = {
	oid: string,
	/**  Git order: the first parent is the mainline, which lane allocation relies on. */
	parents: string[],
	summary: string,
	authorName: string,
	authorEmail: string,
	/**  specta refuses `i64`; Unix seconds stay far below 2^53, so a number is exact. */
	timestamp: number,
	tzOffsetMinutes: number,
};

export type ConflictSide = "base" | "ours" | "theirs";

/**  Named rather than a tuple: positional optional strings reorder silently across IPC. */
export type ConflictText = {
	base: string | null,
	ours: string | null,
	theirs: string | null,
};

/**
 *  One row the frontend asks for in a context menu. Ids are palette command ids, so the
 *  chosen item travels back through the same `menu-command` event as the menu bar.
 */
export type ContextItem = {
	id: string,
	label: string,
	enabled: boolean,
	separator?: boolean,
};

/**
 *  What a batch diff came back with. A request the user has already moved on from stops
 *  between files rather than finishing work nobody will look at.
 */
export type DiffBatch = { kind: "ready"; files: FileDiffEntry[] } | 
/**  A newer request for the same repository started while this one was running. */
{ kind: "superseded" };

export type DiffOptions = {
	algorithm: Algorithm,
	contextLines: number,
	ignoreWhitespace: Whitespace,
	ignoreBlankLines: boolean,
	wordDiff: boolean,
	detectMoves: boolean,
};

export type DiffRow = { kind: "context"; old: number; new: number; text: string } | { kind: "delete"; old: number; text: string; inline: ([number, number])[]; moved?: boolean; 
/**  Both ends of one move carry the same number, so the UI can draw the pair. */
moveId?: number | null; moveScope?: MoveScope | null; 
/**
 *  The file ends on this row without a final newline; a unified diff prints
 *  `\ No newline at end of file` underneath it.
 */
noNewline?: boolean } | { kind: "insert"; new: number; text: string; inline: ([number, number])[]; moved?: boolean; moveId?: number | null; moveScope?: MoveScope | null; noNewline?: boolean } | { kind: "collapsed"; count: number };

